def control(o):
 h=o['hitch_deg']; th=math.radians(-h); cam=o['views'].get('camera'); steer=1.5*h
 if cam:
  sides=[[],[]]
  for b,d in cam['walls']:
   a=math.radians(b); x=d*math.cos(a); y=d*math.sin(a)
   s=-x*math.cos(th)-y*math.sin(th); z=-x*math.sin(th)+y*math.cos(th)
   if s>0.3: sides[z>0].append((s,z))
  L=3.5; vals=[]
  for pts in sides:
   pts=sorted(pts,key=lambda p:abs(p[0]-L))[:5]
   if len(pts)<2: break
   w=[1/(0.3+(s-L)**2) for s,z in pts]; sw=sum(w); mx=sum(p[0]*v for p,v in zip(pts,w))/sw; my=sum(p[1]*v for p,v in zip(pts,w))/sw
   slope=sum(v*(s-mx)*(z-my) for (s,z),v in zip(pts,w))/(0.05+sum(v*(s-mx)**2 for (s,z),v in zip(pts,w)))
   vals.append(my+slope*(L-mx))
  if len(vals)==2:
   center=sum(vals)/2
   hd=max(-30,min(30,math.degrees(math.atan2(5.2*center,L*L))))
   steer=0.75*h+2.1*(h-hd)
 return (max(-34,min(34,steer)),-0.7,-23)

